// CSD_RATIONALE_BEGIN
// Strategy: GSM-Symbolic math word problems answered with free chain-of-thought
// reasoning followed by a parser-constrained arithmetic expression enclosed in
// << ... >> delimiters.  We prepend task guidance, then spend most of the budget
// on free reasoning (Phase 1, using UnconstrainedChunk which self-stops on "<<").
// If the model never opens the span, we force one (Phase 2, OpenConstrainedSpan).
// Finally we hand the remaining budget to CloseSpanWithinBudget (Phase 3), which
// generates a valid expression token by token and appends ">>" once the parser
// reports completeness.  The evaluator model is Qwen/Qwen3.5-2B, stepTokenBudget=1.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   - Initialization: currentConstrainedOut := currentConstrained; the
//     precondition provides insideConstrained ==> parser.IsValidPrefix(currentConstrained),
//     so the invariant holds from the first assignment.
//   - Phase 1 (UnconstrainedChunk): while stoppedOnOpenSpan is false,
//     insideConstrainedOut stays false and the antecedent is vacuously satisfied.
//     When stoppedOnOpenSpan is true, EnterObservedConstrainedSpan resets
//     currentConstrainedOut := [] and parser.IsValidPrefix([]) holds by the
//     parser precondition.
//   - Phase 2 (OpenConstrainedSpan): likewise resets currentConstrainedOut := [],
//     which parser.IsValidPrefix([]) satisfies.
//   - Phase 3 (CloseSpanWithinBudget): the helper's postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut) on its return, so the
//     invariant is re-established after the assignment.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//   - Initialization: generated := generatedPrefix, cost := 0, so equality holds.
//   - Phase 1: UnconstrainedChunk guarantees |generatedOut| <= |generated| +
//     stepsUsed; cost grows by stepsUsed, so the bound is preserved.
//   - Phase 2: OpenConstrainedSpan appends exactly one delimiter token; cost += 1,
//     so |generated| grows by at most 1 while cost grows by exactly 1.
//   - Phase 3: CloseSpanWithinBudget guarantees |generatedOut| <= |generated| +
//     bud3; cost increases by exactly bud3 (= maxSteps - cost_before_phase3), so
//     the total cost reaches at most maxSteps and the length bound is satisfied.
// CSD_PROOF_SKETCH_END

// ── Initialize all out-parameters ────────────────────────────────────────────
generated             := generatedPrefix;
insideConstrainedOut  := insideConstrained;
currentConstrainedOut := currentConstrained;
cost                  := 0;

if maxSteps == 0 {
  return;
}

// ── Task guidance ─────────────────────────────────────────────────────────────
helpers.AppendTaskGuidance(lm,
  "Think step by step. End your answer with: The answer is <<EXPR>> " +
  "(using << and >> as delimiters) where EXPR is a concise numeric expression " +
  "using the variable names from the problem and standard arithmetic " +
  "(+, -, *, /, parentheses). Do not include curly braces in EXPR.");

// ── Budget split ──────────────────────────────────────────────────────────────
// Reserve at least 150 steps for the constrained expression phase.
var constrainedReserve: nat := 150;
var freeBudget: nat;
if maxSteps > constrainedReserve {
  freeBudget := maxSteps - constrainedReserve;
} else {
  freeBudget := 0;
}

// ── Phase 1: Free chain-of-thought (self-stops on "<<") ───────────────────────
if !insideConstrainedOut && freeBudget > 0 {
  var cg1, soo1, soe1, su1 :=
    helpers.UnconstrainedChunk(lm, prompt, generated, freeBudget, "<<", eosToken);
  generated := cg1;
  cost      := cost + su1;
  if soo1 {
    // Model already appended "<<"; enter constrained mode without re-emitting it.
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated             := eg1;
    insideConstrainedOut  := ei1;
    currentConstrainedOut := ec1;
  }
}

// ── Phase 2: Force open constrained span if model never emitted "<<" ─────────
if !insideConstrainedOut && cost < maxSteps {
  var og2, oi2, oc2 := helpers.OpenConstrainedSpan(lm, generated);
  generated             := og2;
  insideConstrainedOut  := oi2;
  currentConstrainedOut := oc2;
  cost                  := cost + 1;
}

// ── Phase 3: Constrained expression + close within remaining budget ───────────
if insideConstrainedOut && cost < maxSteps {
  var bud3: nat := maxSteps - cost;
  var wg3, wi3, wc3 :=
    helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud3);
  generated             := wg3;
  insideConstrainedOut  := wi3;
  currentConstrainedOut := wc3;
  cost                  := cost + bud3;
}
